+function createFileInput(options = {}, render = shallow) {
+  const {
+    field = { value: [] },
+    form = {},
+    ...props
+  } = options;
+
+  return render(<FileInput
+    { ...props }
+    field={ field }
+    form={ form }
+  />);
+}
+
+function createFile(options = {}) {
+  return {
+    name: 'file',
+    lastModified: 1,
+    contents: 'contents',
