+  };
+}
+
+function createFileDescriptor(file = {}) {
+  return {
+    name: 'file',
+    lastModified: 1,
+    contents: file
+  };
+}
+
+function setFiles(input, files) {
+  sinon.stub(input.getDOMNode(), 'files').value(files);
+}

