+			},
+			want: want{
+				uri: "mysql://user:password@unix(/cloudsql/project-id:region-name:instance-name)/dbname",
+			},
+		},
+		{
+			name: "error invalid url",
+			given: given{
+				dsn: "not-a-url",
+			},
+			want: want{
+				hasError: true,
+			},
+		},
+	}
+
