+		tc := tc
+		t.Run(tc.name, func(t *testing.T) {
+			t.Parallel()
+
+			url, err := parseDSN(tc.given.dsn)
+
+			if tc.want.hasError {
+				assert.Error(t, err)
+				return
+			}
+
+			assert.NoError(t, err)
+			assert.Equal(t, tc.want.uri, url)
+		})
+	}
+}

